    S = df['S'].values; I = df['I'].values
    return p['Vmax']*S/(p['Km']*(1+I/p['Ki']) + S*(1+I/(p['alpha']*p['Ki'])))

PARAMS = ['Vmax','Km','Ki','beta']
def predict(df, p):
    S = df['S'].values; I = df['I'].values
    # partial inhibition: ES-bound inhibitor retains beta*Vmax activity (competitive+ESI term)
    return (p['Vmax']*S + p['beta']*p['Vmax']*S*I/p['Ki']) / (p['Km']*(1+I/p['Ki']) + S*(1+I/p['Ki']))

